```json
{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Payment webhook endpoint", "Order service", "Order state updater"],
    "dataStores": ["Orders database"],
    "externalServices": ["Payment provider"],
    "trustBoundaries": ["Internet to public webhook endpoint", "Payment provider to order service"],
    "dataClasses": ["payment"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Spoofing",
      "title": "Anyone on the internet can fake a payment event and get goods for free",
      "scenario": "The webhook is public with no signature or shared-secret check, so an attacker places an order, notes its id, then POSTs a JSON body with that order id and status paid directly to the endpoint. The order is marked paid and fulfilled without any money moving. Repeating this at scale causes direct, unbounded financial loss.",
      "component": "Payment webhook endpoint",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." },
        { "quote": "Our payment webhook endpoint receives events from the payment provider and marks orders as paid." }
      ],
      "cwe": ["CWE-306", "CWE-345"],
      "plainLanguage": "Because nothing checks that the message really came from the payment provider, a stranger can tell your system an order was paid when it was not.",
      "requirement": {
        "title": "Verify webhook authenticity before changing order state",
        "given": "an inbound request to the payment webhook endpoint",
        "when": "the request has no valid provider signature (HMAC/mTLS) over the raw body, or the signature does not match",
        "then": "the request is rejected with no change to any order and the attempt is recorded"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Attacker can mark other customers' orders paid by guessing order ids",
      "scenario": "The endpoint accepts any order id with no check that the event belongs to a real provider transaction for that order. An attacker enumerates or guesses order ids belonging to other customers and marks them paid, releasing other people's goods, cancelling collection, or corrupting settlement and reconciliation across many accounts.",
      "component": "Order state updater",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." }
      ],
      "cwe": ["CWE-639", "CWE-346"],
      "plainLanguage": "The endpoint trusts whatever order number you send, so someone can change orders that are not theirs.",
      "requirement": {
        "title": "Bind each webhook event to a provider transaction for that order",
        "given": "an authenticated webhook event referencing an order id",
        "when": "the event's provider transaction/payment reference does not match a transaction recorded for that exact order",
        "then": "the order state is left unchanged and the mismatch is flagged for investigation"
      }
    },
    {
      "stride": "Tampering",
      "title": "Paid amount and currency are never checked against the order total",
      "scenario": "The body carries only an order id and status, so nothing compares the amount, currency and payment status against what the order should cost. An attacker (or a real underpayment/partial-capture event) results in a $5 payment marking a $500 order paid, or a foreign-currency amount being accepted at face value, causing revenue loss that only surfaces at reconciliation.",
      "component": "Order service",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." }
      ],
      "cwe": ["CWE-840", "CWE-20"],
      "plainLanguage": "The system marks an order paid without checking that the right amount in the right currency was actually paid.",
      "requirement": {
        "title": "Validate amount, currency and event type before marking paid",
        "given": "a verified payment event for an order",
        "when": "the event amount or currency does not equal the order's outstanding total, or the event type is not a successful capture",
        "then": "the order is not marked paid and is routed to manual payment review"
      }
    },
    {
      "stride": "Tampering",
      "title": "Captured events can be replayed because there is no idempotency or replay window",
      "scenario": "Nothing in the design deduplicates events or rejects old ones. An attacker who observes or obtains one genuine paid event (logs, proxy, provider retry) resends it repeatedly, re-marking refunded or cancelled orders as paid, triggering duplicate fulfilment or duplicate payout, and corrupting order history.",
      "component": "Payment webhook endpoint",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Our payment webhook endpoint receives events from the payment provider and marks orders as paid." }
      ],
      "cwe": ["CWE-294", "CWE-349"],
      "plainLanguage": "The same payment message can be sent again and again, so one real payment can be reused to pay for more orders.",
      "requirement": {
        "title": "Make webhook processing idempotent and time-bounded",
        "given": "a verified payment event carrying a provider event id and timestamp",
        "when": "the event id has already been processed or the timestamp is outside the accepted freshness window",
        "then": "the event is acknowledged but produces no further state change"
      }
    },
    {
      "stride": "Tampering",
      "title": "Arbitrary status values let orders jump or reverse through states",
      "scenario": "The endpoint accepts any status in the JSON body with no state machine. A caller can set a refunded order back to paid, move a cancelled order to paid, or inject an unknown status that downstream fulfilment interprets permissively. This bypasses refund and cancellation controls and makes order state untrustworthy for finance.",
      "component": "Order state updater",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." }
      ],
      "cwe": ["CWE-20", "CWE-841"],
      "plainLanguage": "Any status word is accepted, so an order can be pushed backwards or into a state that should not be possible.",
      "requirement": {
        "title": "Enforce an allow-listed order state machine",
        "given": "a verified event proposing a new order status",
        "when": "the status is not in the allow-list or the transition from the current status is not permitted",
        "then": "the request is rejected and the order keeps its current status"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Responses to the public endpoint reveal which order ids exist",
      "scenario": "Because the endpoint is public and takes an order id, differing responses or timings for known versus unknown ids give an attacker an oracle to enumerate valid order ids and infer order volume and sequence. This both enables the order-id abuse above and leaks commercial information about payment volumes to anyone.",
      "component": "Payment webhook endpoint",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." }
      ],
      "cwe": ["CWE-204", "CWE-209"],
      "plainLanguage": "The endpoint answers differently for real and fake order numbers, which lets outsiders work out which orders exist.",
      "requirement": {
        "title": "Return uniform responses to unauthenticated callers",
        "given": "an inbound webhook request that fails signature verification or references an unknown order",
        "when": "the endpoint responds",
        "then": "the status code, body and timing are indistinguishable from the valid-order case and carry no order detail"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Unauthenticated public endpoint writes to the orders database on every request",
      "scenario": "Any JSON body is accepted and each request causes order lookups and writes, so an attacker floods the public endpoint with large or deeply nested bodies and high-cardinality order ids. Database write contention and lock pressure on the orders table stalls checkout and genuine provider callbacks, so real payments are lost during the attack.",
      "component": "Payment webhook endpoint",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The endpoint is public and accepts any JSON body with an order id and status." }
      ],
      "cwe": ["CWE-770", "CWE-400"],
      "plainLanguage": "Anyone can hammer the open endpoint with junk payments and slow down or break real checkouts.",
      "requirement": {
        "title": "Reject unverified traffic before doing database work",
        "given": "an inbound request to the payment webhook endpoint",
        "when": "the body exceeds a maximum size/nesting depth or the signature is not yet verified",
        "then": "the request is rejected before any order lookup or write, and source-level request limits apply"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No provider event reference, so a disputed 'paid' order cannot be proven",
      "scenario": "Orders are marked paid from a body containing only an order id and status, with no stored provider event id, payload or signature. When a customer disputes a charge or a fraudulent paid event is found, the team cannot show whether the state change came from the provider or from an attacker, and cannot scope how many orders were affected.",
      "component": "Order service",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Our payment webhook endpoint receives events from the payment provider and marks orders as paid." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Nothing records which payment message changed an order, so you cannot prove later whether a payment was real.",
      "requirement": {
        "title": "Persist the provider event evidence with every payment state change",
        "given": "an order status change caused by a webhook event",
        "when": "the change is written",
        "then": "the provider event id, raw payload hash, signature result and received timestamp are stored immutably alongside it"
      }
    }
  ]
}
```
